
"use client";

// Generated by philote from component SwipeDeck. SwipeDeckBody's body is
// written by a model and pinned in philote.lock (D-019).
/* eslint-disable @typescript-eslint/no-unused-vars -- every component gets the same imports */
import { useEffect, useRef, useState, useTransition } from "react";

import * as Icons from "lucide-react";
import { toast } from "sonner";

import { formatBool, formatDate, formatDateTime } from "@/lib/format";
import type { SwipeDeckProps } from "@/lib/reads";
import { cn } from "@/lib/utils";

import { Badge } from "@/components/ui/badge";
import {
    Card,
    CardAction,
    CardContent,
    CardDescription,
    CardFooter,
    CardHeader,
    CardTitle,
} from "@/components/ui/card";
import { Separator } from "@/components/ui/separator";

import Mark from "@/components/common/mark";

import { swipe, type SwipeResult } from "@/lib/actions/swipe-deck-call";

// The wrapper hands the body its props, and what the template places beside them.
export default function SwipeDeck(props: SwipeDeckProps) {
    return <SwipeDeckBody {...props} swipe={swipe} />;
}

// The spec's words for SwipeDeck, in order. The body shows every one.
const says = ["You've seen every horse. Check back later.", "It's a match!", "Keep swiping"] as const;

function SwipeDeckBody({ deck, swipe }: SwipeDeckProps & { swipe: (input: { target: string; liked: boolean }) => Promise<SwipeResult> }): React.ReactNode {
    const [gone, setGone] = useState<string[]>([]);
    const [dx, setDx] = useState(0);
    const [dragging, setDragging] = useState(false);
    const [match, setMatch] = useState<{
      horse: SwipeDeckProps["deck"][number];
      matchedAt: string;
    } | null>(null);
    const startX = useRef<number | null>(null);
    const dxRef = useRef(0);
    const keepRef = useRef<HTMLButtonElement | null>(null);
    const [, startTransition] = useTransition();

    const remaining = deck.filter((h) => !gone.includes(h.id));
    const top = remaining[0];
    const threshold = 110;

    useEffect(() => {
      if (match) keepRef.current?.focus();
    }, [match]);

    const decide = (liked: boolean) => {
      if (!top || match) return;
      const horse = top;
      const id = horse.id;
      setGone((g) => [...g, id]);
      setDx(0);
      dxRef.current = 0;
      setDragging(false);
      startX.current = null;
      startTransition(async () => {
        const result = await swipe({ target: id, liked });
        if (!result.ok) {
          toast.error(result.error);
          setGone((g) => g.filter((x) => x !== id));
          return;
        }
        if (result.value.match) {
          setMatch({ horse, matchedAt: result.value.match.matched_at });
        }
      });
    };

    const onPointerDown = (e: React.PointerEvent<HTMLDivElement>) => {
      if ((e.target as HTMLElement).closest("button")) return;
      e.currentTarget.setPointerCapture(e.pointerId);
      startX.current = e.clientX;
      dxRef.current = 0;
      setDragging(true);
    };

    const onPointerMove = (e: React.PointerEvent<HTMLDivElement>) => {
      if (startX.current === null) return;
      const next = e.clientX - startX.current;
      dxRef.current = next;
      setDx(next);
    };

    const onPointerEnd = () => {
      if (startX.current === null) return;
      const final = dxRef.current;
      startX.current = null;
      setDragging(false);
      if (final > threshold) decide(true);
      else if (final < -threshold) decide(false);
      else {
        setDx(0);
        dxRef.current = 0;
      }
    };

    const stack = remaining.slice(0, 2).reverse();
    const likeOpacity = Math.max(0, Math.min(1, dx / threshold));
    const passOpacity = Math.max(0, Math.min(1, -dx / threshold));

    return (
      <section className="relative w-full overflow-hidden bg-linear-to-b from-primary/10 via-background to-background text-foreground">
        <div
          aria-hidden
          className="pointer-events-none absolute -top-24 left-1/2 size-96 -translate-x-1/2 rounded-full bg-primary/10 blur-3xl"
        />
        <div className="relative mx-auto flex max-w-5xl flex-col items-center gap-8 px-4 py-8 sm:px-6 sm:py-12">
          {top ? (
            <>
              <div className="grid w-full max-w-sm sm:max-w-md">
                {stack.map((horse) => {
                  const isTop = horse.id === top.id;
                  return (
                    <div
                      key={horse.id}
                      className={cn(
                        "col-start-1 row-start-1",
                        isTop
                          ? "z-10 cursor-grab touch-none select-none active:cursor-grabbing"
                          : "pointer-events-none z-0 translate-y-4 scale-95 opacity-70 transition-transform duration-300",
                        isTop && !dragging && "transition-transform duration-300 ease-out"
                      )}
                      style={
                        isTop
                          ? { transform: `translateX(${dx}px) rotate(${dx / 18}deg)` }
                          : undefined
                      }
                      aria-hidden={isTop ? undefined : true}
                      onPointerDown={isTop ? onPointerDown : undefined}
                      onPointerMove={isTop ? onPointerMove : undefined}
                      onPointerUp={isTop ? onPointerEnd : undefined}
                      onPointerCancel={isTop ? onPointerEnd : undefined}
                    >
                      <Card className="relative h-full overflow-hidden rounded-xl border bg-card pt-0 text-card-foreground shadow-lg">
                        <Mark
                          name={horse.name}
                          className="pointer-events-none aspect-[4/3] w-full rounded-none"
                        />
                        {isTop && (
                          <>
                            <div
                              aria-hidden
                              className="pointer-events-none absolute left-4 top-4 z-20 flex size-14 items-center justify-center rounded-full border-2 border-primary bg-background/80 text-primary"
                              style={{ opacity: likeOpacity }}
                            >
                              <Icons.Heart className="size-7 fill-current" />
                            </div>
                            <div
                              aria-hidden
                              className="pointer-events-none absolute right-4 top-4 z-20 flex size-14 items-center justify-center rounded-full border-2 bg-background/80 text-muted-foreground"
                              style={{ opacity: passOpacity }}
                            >
                              <Icons.X className="size-7" />
                            </div>
                          </>
                        )}
                        <CardHeader className="gap-2">
                          <CardTitle className="font-heading text-3xl font-bold leading-tight sm:text-4xl">
                            {horse.name}
                          </CardTitle>
                          <CardDescription className="flex items-baseline gap-1.5 text-base text-muted-foreground">
                            <span className="text-xs uppercase tracking-wide">Age</span>
                            <span className="text-lg font-semibold text-foreground">{horse.age}</span>
                          </CardDescription>
                          <CardAction>
                            <Badge variant="secondary" className="capitalize">
                              {horse.breed}
                            </Badge>
                          </CardAction>
                        </CardHeader>
                        <Separator />
                        <CardContent className="flex-1">
                          <p className="line-clamp-4 whitespace-pre-line text-base leading-relaxed text-muted-foreground">
                            {horse.bio}
                          </p>
                        </CardContent>
                      </Card>
                    </div>
                  );
                })}
              </div>
              <div className="flex items-center justify-center gap-8">
                <button
                  type="button"
                  aria-label="Pass"
                  onClick={() => decide(false)}
                  disabled={!!match}
                  className="flex size-16 items-center justify-center rounded-full border bg-card text-muted-foreground shadow-md transition hover:scale-105 hover:bg-accent focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring active:scale-95 disabled:opacity-50"
                >
                  <Icons.X className="size-7" />
                </button>
                <button
                  type="button"
                  aria-label="Like"
                  onClick={() => decide(true)}
                  disabled={!!match}
                  className="flex size-16 items-center justify-center rounded-full bg-primary text-primary-foreground shadow-md transition hover:scale-105 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring active:scale-95 disabled:opacity-50"
                >
                  <Icons.Heart className="size-7 fill-current" />
                </button>
              </div>
            </>
          ) : (
            <Card className="w-full max-w-md rounded-xl border bg-muted text-muted-foreground">
              <CardContent className="flex flex-col items-center gap-4 py-12 text-center">
                <Icons.Heart aria-hidden className="size-10" />
                <p className="font-heading text-lg">{says[0]}</p>
              </CardContent>
            </Card>
          )}
        </div>
        {match && (
          <div
            role="dialog"
            aria-modal="true"
            aria-labelledby="swipe-match-title"
            className="absolute inset-0 z-30 flex items-center justify-center bg-background/80 px-4 backdrop-blur-sm animate-in fade-in"
          >
            <div
              aria-hidden
              className="pointer-events-none absolute inset-0 bg-linear-to-br from-primary/30 via-transparent to-accent/60"
            />
            <div
              aria-hidden
              className="pointer-events-none absolute left-1/2 top-1/2 size-80 -translate-x-1/2 -translate-y-1/2 rounded-full bg-primary/20 blur-3xl"
            />
            <div className="relative flex w-full max-w-sm flex-col items-center gap-6 rounded-xl border bg-card p-8 text-center text-card-foreground shadow-2xl animate-in zoom-in-95">
              <div className="relative">
                <Mark
                  name={match.horse.name}
                  className="size-28 ring-4 ring-primary ring-offset-4 ring-offset-card"
                />
                <span
                  aria-hidden
                  className="absolute -bottom-2 -right-2 flex size-10 items-center justify-center rounded-full bg-primary text-primary-foreground shadow-md"
                >
                  <Icons.Heart className="size-5 fill-current" />
                </span>
              </div>
              <div className="flex flex-col gap-2">
                <h2
                  id="swipe-match-title"
                  className="font-heading text-3xl font-bold text-primary sm:text-4xl"
                >
                  {says[1]}
                </h2>
                <p className="font-heading text-xl font-semibold">{match.horse.name}</p>
                <time dateTime={match.matchedAt} className="text-sm text-muted-foreground">
                  {formatDateTime(match.matchedAt)}
                </time>
              </div>
              <button
                ref={keepRef}
                type="button"
                onClick={() => setMatch(null)}
                className="w-full rounded-lg bg-primary px-6 py-3 font-semibold text-primary-foreground shadow-md transition hover:bg-primary/90 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring active:scale-95"
              >
                {says[2]}
              </button>
            </div>
          </div>
        )}
      </section>
    );
}
